                used[c] = u
        return False

    if rec(0):
        return ["".join(row) for row in grid]
    return None


def ref(inp):
    t = inp.split()
    n = int(t[0])
    R, Cs = t[1], t[2]
    res = _solve(n, R, Cs)
    if res is None:
        return "No"
    return "Yes\n" + "\n".join(res)


def same(inp, expected, got):
    t = inp.split()
    n = int(t[0])
    R, Cs = t[1], t[2]
    g = got.split()
    exp_yes = expected.split()[0] == "Yes"
    if not g:
        return False
    if not exp_yes:
        return g == ["No"]
    if g[0] != "Yes":
        return False
    rows = g[1:]
    if len(rows) != n:
        return False
    if any(len(row) != n for row in rows):
        return False
    if any(ch not in ".ABC" for row in rows for ch in row):
        return False
    for row in rows:
        if sorted(ch for ch in row if ch != '.') != ['A', 'B', 'C']:
            return False
    for j in range(n):
        col = [rows[i][j] for i in range(n)]
        if sorted(ch for ch in col if ch != '.') != ['A', 'B', 'C']:
            return False
    for i in range(n):
        filled = [(j, rows[i][j]) for j in range(n) if rows[i][j] != '.']
        if filled[0][1] != R[i]:
            return False
    for j in range(n):
        filled = [(i, rows[i][j]) for i in range(n) if rows[i][j] != '.']
        if filled[0][1] != Cs[j]:
            return False
    return True
